// src/components/Dashboard.js
import React from 'react';
import { useNavigate } from 'react-router-dom';
import '../App.css';

const Dashboard = ({ user }) => {
  const navigate = useNavigate();

  return (
    <div className="container">
      <div className="upload-card" style={{ padding: '2rem', borderRadius: '12px' }}>
        <h1 className="title text-center">Hello, {user?.name}!</h1>
        <p className="subtitle text-center mb-4">Choose the type of area you want to monitor</p>

        <div className="row" style={{ display: 'flex', gap: '2rem', justifyContent: 'center', flexWrap: 'wrap' }}>
          {/* Prohibited Area Section */}
          <div className="area-card" style={{ flex: '1', minWidth: '280px' }}>
            <h3 style={{ color: '#ff8c00' }}>Prohibited Area</h3>
            <ul style={{ paddingLeft: '1.2rem', lineHeight: '1.6' }}>
              <li>Standard surveillance zones</li>
              <li>Moderate risk level</li>
              <li>Real-time human detection enabled</li>
            </ul>
            <button
              className="submit-button"
              style={{ marginTop: '1rem', width: '100%' }}
              onClick={() => navigate('/prohibited-area')}
            >
              Monitor Prohibited Area
            </button>
          </div>

          {/* Strictly Prohibited Area Section */}
          <div className="area-card" style={{ flex: '1', minWidth: '280px' }}>
            <h3 style={{ color: '#d32f2f' }}>Strictly Prohibited Area</h3>
            <ul style={{ paddingLeft: '1.2rem', lineHeight: '1.6' }}>
              <li>High-security zones</li>
              <li>Immediate alerts on breach</li>
              <li>Enhanced monitoring protocols</li>
            </ul>
            <button
              className="submit-button"
              style={{ marginTop: '1rem', width: '100%' }}
              onClick={() => navigate('/strictly-prohibited-area')}
            >
              Monitor Strictly Prohibited Area
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
